PAGE = "<!doctype html>\n<html lang=\"__LANG__\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex\"><meta name=\"theme-color\" content=\"#09090B\"><title>FNauto REMOTE</title>\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\"><meta name=\"apple-mobile-web-app-title\" content=\"FNauto\">\n<link rel=\"manifest\" href=\"/manifest.json__QS__\"><link rel=\"apple-touch-icon\" href=\"/icon-180.png__QS__\"><link rel=\"icon\" type=\"image/svg+xml\" href=\"/icon.svg__QS__\">\n<style>\n:root{--bg:#09090B;--sf:#121215;--ln:#232329;--ln2:#27272A;--fg:#F4F4F6;--mut:#71717A;--ok:#10B981;--warn:#F59E0B;--bad:#EF4444;\n--mono:'JetBrains Mono','SF Mono','Consolas',ui-monospace,monospace;--sans:-apple-system,'Segoe UI',Roboto,system-ui,sans-serif}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;margin:0;padding:0}\nhtml,body{height:100dvh;overflow:hidden;-webkit-touch-callout:none;overscroll-behavior:none;background:var(--bg);color:var(--fg);font:13px/1.4 var(--sans);touch-action:manipulation;-webkit-user-select:none;user-select:none}\n.init *{transition:none!important}\nbody{display:flex;flex-direction:column;gap:8px;padding:0 12px calc(10px + env(safe-area-inset-bottom));max-width:560px;margin:auto}\n.lbl{font:600 10px/1 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--mut)}\n.num{font-family:var(--mono);font-variant-numeric:tabular-nums}\nsvg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:square;stroke-linejoin:miter;flex:none}\n/* top bar */\n#top{height:44px;flex:none;display:flex;align-items:center;gap:8px;padding-top:env(safe-area-inset-top);box-sizing:content-box}\n#logo{font:600 10px/1 var(--mono);letter-spacing:.06em;color:var(--mut);margin-right:auto;white-space:nowrap}\n#logo b{color:var(--fg);font-weight:600}\n#pill{display:flex;align-items:center;gap:6px;height:26px;padding:0 9px;border:1px solid var(--ln);background:var(--sf);border-radius:13px;font:600 10px/1 var(--mono);letter-spacing:.08em}\n#dot{width:6px;height:6px;border-radius:50%;background:var(--mut)}\n#seg{position:relative;display:flex;height:26px;border:1px solid var(--ln);background:var(--sf);border-radius:6px;overflow:hidden}\n#seg i{position:absolute;top:2px;bottom:2px;left:2px;width:calc((100% - 4px)/3);background:var(--fg);border-radius:4px;transition:transform .16s ease}\n#seg button{position:relative;width:30px;border:0;background:none;color:var(--mut);font:600 11px/1 var(--mono);transition:color .16s}\n#seg button.on{color:var(--bg)}\n/* live view */\n#live{position:relative;flex:none;width:100%;aspect-ratio:16/9;background:#000;border:1px solid var(--ln2);overflow:hidden}\n#live img{position:absolute;inset:0;width:100%;height:100%;object-fit:fill;display:block}\n#nosig{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font:600 10px/1 var(--mono);letter-spacing:.12em;color:var(--mut)}\n#ov{position:absolute;left:6px;top:6px;display:flex;gap:8px;padding:4px 6px;background:rgba(9,9,11,.72);font:600 9px/1 var(--mono);letter-spacing:.06em;color:#A1A1AA;pointer-events:none}\n#tg{position:absolute;right:6px;bottom:6px;display:flex;align-items:center;gap:7px;padding:4px 6px;background:rgba(9,9,11,.72);border:0;color:#A1A1AA;font:600 9px/1 var(--mono);letter-spacing:.06em}\n#tg s{position:relative;width:22px;height:12px;border:1px solid var(--mut);border-radius:6px;transition:background .15s,border-color .15s}\n#tg s::after{content:\"\";position:absolute;top:1px;left:1px;width:8px;height:8px;border-radius:50%;background:var(--mut);transition:transform .15s,background .15s}\n#tg.on{color:var(--fg)}#tg.on s{background:var(--fg);border-color:var(--fg)}#tg.on s::after{transform:translateX(10px);background:var(--bg)}\n.rip{position:absolute;width:44px;height:44px;margin:-22px 0 0 -22px;border:1.5px solid #fff;border-radius:50%;pointer-events:none;animation:rip .5s ease-out forwards}\n@keyframes rip{from{transform:scale(.3);opacity:.9}to{transform:scale(1.5);opacity:0}}\n/* meters */\n#met{flex:1 1 auto;max-height:112px;min-height:64px;display:grid;grid-template-columns:repeat(3,1fr);background:var(--sf);border:1px solid var(--ln)}\n#met>div{padding:9px 12px 10px;display:flex;flex-direction:column;justify-content:center}#met>div+div{border-left:1px solid var(--ln)}\n#met .num{display:block;margin-top:7px;font-size:26px;line-height:1;font-weight:500;letter-spacing:-.02em}\n#aux{flex:none;display:flex;justify-content:space-between;gap:8px;padding:7px 10px;border:1px solid var(--ln);background:var(--sf);font:600 9px/1 var(--mono);letter-spacing:.06em;color:var(--mut);white-space:nowrap;overflow:hidden}\n#aux span{overflow:hidden;text-overflow:ellipsis}#aux .on{color:var(--fg)}\n/* deck */\n#deck{flex:2 1 auto;max-height:196px;display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:1.35fr 1fr;gap:8px}\nbutton{font-family:var(--sans);color:var(--fg);transition:transform .08s,background .12s}\nbutton:active{transform:scale(.97)}\n#go{grid-column:1/-1;min-height:56px;border:1px solid var(--fg);background:var(--fg);color:var(--bg);font:600 13px/1 var(--mono);letter-spacing:.14em;border-radius:6px}\n#go.run{background:#2A1215;border-color:var(--bad);color:var(--bad)}\n.key{min-height:48px;display:flex;align-items:center;justify-content:center;gap:7px;background:var(--sf);border:1px solid var(--ln);border-radius:6px;font:600 10px/1 var(--mono);letter-spacing:.1em}\n.key:active{background:#1B1B20}.key.on{border-color:var(--warn);color:var(--warn)}\n/* tactical keypad + hold-to-confirm system actions */\n#kpt{grid-column:1/-1;justify-content:space-between;padding:0 14px;min-height:40px}#kpt b{font-weight:600;color:var(--mut)}\n#deck.open{flex:none;max-height:none;grid-template-rows:auto}body.kpopen{overflow-y:auto}\n#kp{grid-column:1/-1;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}#kp[hidden]{display:none}\n#kp .key{min-height:44px}#kp .wide{grid-column:1/-1}\n#sys{flex:none;display:grid;grid-template-columns:1fr 1fr;gap:8px}#sys .wide{grid-column:1/-1}\n.hold{position:relative;overflow:hidden;min-height:52px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;background:var(--sf);border:1px solid var(--ln);border-radius:6px;font:600 10px/1 var(--mono);letter-spacing:.1em;touch-action:none}\n.hold i{position:absolute;left:0;top:0;bottom:0;width:0;background:#2A1215;transition:none}.hold.go i{width:100%;transition:width 1.5s linear}\n.hold span,.hold small{position:relative}.hold small{font-size:9px;font-weight:600;color:var(--mut);letter-spacing:.08em}\n.hold.danger{border-color:#3a1a1e;color:var(--bad)}.hold.done{border-color:var(--bad)}\n/* log */\n#log{flex:none;height:92px;margin-top:auto;background:#050507;border:1px solid var(--ln);padding:8px 10px;overflow:hidden;font:11px/1.55 var(--mono);display:flex;flex-direction:column;justify-content:flex-end}\n#log div{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#A1A1AA}#log span{color:#52525B;margin-right:8px}\n#toast{position:fixed;left:50%;bottom:calc(14px + env(safe-area-inset-bottom));transform:translateX(-50%);padding:7px 12px;background:var(--sf);border:1px solid var(--ln2);font:600 10px/1 var(--mono);letter-spacing:.1em;opacity:0;pointer-events:none;transition:opacity .15s}\n</style></head><body class=\"init\">\n<div id=\"top\"><div id=\"logo\"><b>FNauto</b> REMOTE</div>\n<div id=\"pill\"><span id=\"dot\"></span><span id=\"st\">IDLE</span></div>\n<div id=\"seg\"><i></i><button data-m=\"A\">A</button><button data-m=\"B\">B</button><button data-m=\"C\">C</button></div></div>\n<div id=\"live\"><img id=\"im\" alt=\"\" style=\"display:none\"><div id=\"nosig\">NO SIGNAL</div>\n<div id=\"ov\"><span>LIVE &middot; 2.5s</span><span id=\"sn\">STATE: IDLE</span><span id=\"el\" class=\"num\">T+00:00:00</span></div>\n<button id=\"tg\" type=\"button\"><span>TOUCH CLICK: <b id=\"tgs\">OFF</b></span><s></s></button></div>\n<div id=\"met\"><div><span class=\"lbl\">Loops</span><span id=\"lp\" class=\"num\">0</span></div>\n<div><span class=\"lbl\">Vault claims</span><span id=\"cl\" class=\"num\">00</span></div>\n<div><span class=\"lbl\">Next Esc</span><span id=\"nx\" class=\"num\">--:--</span></div></div>\n<div id=\"aux\"><span id=\"tn\">TUNE: OFF</span></div>\n<div id=\"deck\"><button id=\"go\" type=\"button\">START SESSION</button>\n<button class=\"key\" id=\"ck\" type=\"button\"><svg viewBox=\"0 0 16 16\"><path d=\"M4 2l8 6-3.5 1L10.5 14 8.5 15 6.5 10 4 12z\"/></svg>LEFT CLICK</button>\n<button class=\"key\" id=\"sp\" type=\"button\"><svg viewBox=\"0 0 16 16\"><path d=\"M2 6v4h12V6\"/></svg>SPACE</button>\n<button class=\"key\" id=\"mu\" type=\"button\"><svg viewBox=\"0 0 16 16\"><path d=\"M2 6h3l4-3v10l-4-3H2z\"/><path d=\"M12 5l3 6M15 5l-3 6\"/></svg>MUTE AUDIO</button>\n<button class=\"key\" id=\"kpt\" type=\"button\"><span>TACTICAL KEYPAD</span><b id=\"kps\">+</b></button>\n<div id=\"kp\" hidden><button class=\"key\" type=\"button\" data-k=\"esc\">ESC</button><button class=\"key\" type=\"button\" data-k=\"w\">W</button><button class=\"key\" type=\"button\" data-k=\"enter\">ENTER</button>\n<button class=\"key\" type=\"button\" data-k=\"a\">A</button><button class=\"key\" type=\"button\" data-k=\"s\">S</button><button class=\"key\" type=\"button\" data-k=\"d\">D</button>\n<button class=\"key wide\" type=\"button\" data-k=\"pickaxe\"><svg viewBox=\"0 0 16 16\"><path d=\"M3 4c3-2 7-2 10 0M8 3v11\"/></svg>PICKAXE</button>\n</div></div>\n<div id=\"sys\"><button class=\"hold\" type=\"button\" data-a=\"sleep\"><i></i><span>STOP &amp; SLEEP PC</span><small>HOLD 1.5s TO CONFIRM</small></button>\n<button class=\"hold danger\" type=\"button\" data-a=\"kill\"><i></i><span>FORCE KILL GAME</span><small>HOLD 1.5s TO CONFIRM</small></button>\n<button class=\"hold wide\" type=\"button\" data-a=\"relaunch\"><i></i><span>RELAUNCH FN</span><small>HOLD 1.5s TO CONFIRM</small></button></div>\n<div id=\"log\"></div><div id=\"toast\"></div>\n<script>\nconst T=new URLSearchParams(location.search).get('token')||'';\nconst $=i=>document.getElementById(i),q=p=>p+(p.includes('?')?'&':'?')+'token='+encodeURIComponent(T);\nconst NAMES={'IDLE':'IDLE','SEARCHING_PLAY':'LOBBY','IN_MATCH':'IN_MATCH','SKIPPING_RESULT':'SKIP','RETURNING_LOBBY':'RETURN','B:LOBBY':'LOBBY','B:LOADING':'LOADING','B:WAITING':'ISLAND_WAIT','B:MENU':'MENU'};\nconst p2=n=>String(Math.max(0,n|0)).padStart(2,'0');\nconst buzz=()=>{try{navigator.vibrate&&navigator.vibrate(15)}catch(e){}};\nlet toastT;function toast(t){const e=$('toast');e.textContent=t;e.style.opacity=1;clearTimeout(toastT);toastT=setTimeout(()=>e.style.opacity=0,1300)}\nasync function act(a,v){buzz();try{const r=await fetch(q('/api/action'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:a,value:v===undefined?'':String(v)})});\nconst j=await r.json();toast(j.ok?'OK':String(j.error||'FAILED').toUpperCase().replace(/_/g,' '));poll()}catch(e){toast('NO LINK')}}\nlet eta=null,etaAt=0,running=false,mode='';\nfunction paint(){let s='--:--';if(running&&eta!==null){const l=Math.max(0,Math.round(eta-(performance.now()-etaAt)/1000));s=p2(l/60)+':'+p2(l%60)}$('nx').textContent=s}\nasync function poll(){try{const j=await (await fetch(q('/api/status'),{cache:'no-store'})).json();\nrunning=!!j.running;eta=(j.eta===null||j.eta===undefined)?null:+j.eta;etaAt=performance.now();\nconst c=j.stuck?'var(--bad)':running?(j.waiting?'var(--warn)':'var(--ok)'):'var(--mut)';\n$('dot').style.background=c;$('st').textContent=j.stuck?'STUCK':running?'RUNNING':'IDLE';$('st').style.color=j.stuck?'var(--bad)':'var(--fg)';\n$('sn').textContent='STATE: '+(NAMES[j.state]||String(j.state).toUpperCase());\nif(j.alert){$('st').textContent='ALERT';$('st').style.color='var(--bad)';$('dot').style.background='var(--bad)';$('sn').textContent='ALERT: '+String(j.alert).toUpperCase().slice(0,60)}\nconst e=j.elapsed|0;$('el').textContent='T+'+p2(e/3600)+':'+p2(e%3600/60)+':'+p2(e%60);\n$('lp').textContent=j.loops;$('cl').textContent=p2(j.claims);\n$('tn').textContent=j.tune||'TUNE: OFF';$('tn').className=j.tune?'on':'';const g=$('go');g.textContent=running?'STOP SESSION':'START SESSION';g.className=running?'run':'';\nmode=j.mode;const bs=[...document.querySelectorAll('#seg button')];bs.forEach(b=>b.classList.toggle('on',b.dataset.m===mode));\nconst ix=Math.max(0,bs.findIndex(b=>b.dataset.m===mode));document.querySelector('#seg i').style.transform='translateX('+ix*100+'%)';\n$('log').innerHTML=(j.log||[]).slice(-4).map(l=>{const m=/^(\\d\\d:\\d\\d:\\d\\d) (.*)$/.exec(l);const d=document.createElement('div');\nif(m){const s=document.createElement('span');s.textContent=m[1];d.append(s,m[2])}else d.textContent=l;return d.outerHTML}).join('');paint()}catch(e){}}\nlet busy=false;function frame(){if(busy)return;busy=true;const n=new Image();\nn.onload=()=>{busy=false;const im=$('im');im.src=n.src;im.style.display='block';$('nosig').style.display='none'};\nn.onerror=()=>{busy=false;$('im').style.display='none';$('nosig').style.display='flex'};n.src=q('/api/frame.jpg?t='+Date.now())}\nlet touch=false;\n$('tg').onclick=e=>{e.stopPropagation();touch=!touch;$('tg').classList.toggle('on',touch);$('tgs').textContent=touch?'ON':'OFF';buzz()};\n$('live').addEventListener('pointerdown',e=>{if(!touch||e.target.closest('#tg'))return;const r=$('live').getBoundingClientRect();\nconst rx=Math.min(1,Math.max(0,(e.clientX-r.left)/r.width)),ry=Math.min(1,Math.max(0,(e.clientY-r.top)/r.height));\nconst d=document.createElement('span');d.className='rip';d.style.left=(rx*100)+'%';d.style.top=(ry*100)+'%';$('live').append(d);setTimeout(()=>d.remove(),520);\nact('tap',rx.toFixed(4)+','+ry.toFixed(4))});\nasync function relaunch(){buzz();try{const r=await fetch(q('/api/relaunch'),{method:'POST',headers:{'content-type':'application/json'},body:'{}'});\nconst j=await r.json();toast(j.ok?'OK':String(j.error||'FAILED').toUpperCase().replace(/_/g,' '));poll()}catch(e){toast('NO LINK')}}\n$('go').onclick=()=>act('toggle');$('ck').onclick=()=>act('click');$('sp').onclick=()=>act('space');$('mu').onclick=()=>act('mute');\ndocument.querySelectorAll('#seg button').forEach(b=>b.onclick=()=>act('mode',b.dataset.m));\n$('kpt').onclick=()=>{const k=$('kp');k.hidden=!k.hidden;$('kps').textContent=k.hidden?'+':'-';$('deck').classList.toggle('open',!k.hidden);document.body.classList.toggle('kpopen',!k.hidden);buzz()};\ndocument.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>act('key',b.dataset.k));\nconst quiet=(a,v)=>fetch(q('/api/action'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:a,value:v})}).catch(()=>{});\ndocument.querySelectorAll('.hold').forEach(b=>{let t=null;\nconst stop=()=>{clearTimeout(t);t=null;b.classList.remove('go')};\nb.addEventListener('contextmenu',e=>e.preventDefault());\nb.addEventListener('pointerdown',e=>{e.preventDefault();try{b.setPointerCapture(e.pointerId)}catch(x){}buzz();stop();void b.offsetWidth;b.classList.add('go');quiet('arm',b.dataset.a);\nt=setTimeout(()=>{t=null;b.classList.remove('go');b.classList.add('done');buzz();(b.dataset.a==='relaunch'?relaunch():act(b.dataset.a));setTimeout(()=>b.classList.remove('done'),1500)},1500)});\n['pointerup','pointercancel','pointerleave'].forEach(n=>b.addEventListener(n,()=>{if(t)stop()}))});\npoll().then(()=>requestAnimationFrame(()=>document.body.classList.remove('init')));frame();setInterval(poll,1500);setInterval(frame,2500);setInterval(paint,250);\n</script></body></html>"
